def fold_line_discounts(apps, schema_editor):
    """Unpaid invoices: move their line discounts onto the invoice as one rand
    discount (totals unchanged). Paid / cancelled ones keep their lines as
    issued. Any invoice that had line discounts stops auto-discounting unless
    its discount was a bundle (e.g. "All 4 modules"), so nothing changes by
    itself on the next edit."""
