    Discount = apps.get_model('shop', 'Discount')
    bundle_names = {d.name.strip().lower() for d in Discount.objects.filter(
        code__isnull=True, discount_type='amount') if d.products.exists()}

    discounted = InvoiceItem.objects.filter(discount_amount__gt=0).values_list('invoice_id', flat=True)
    for invoice in Invoice.objects.filter(pk__in=set(discounted)):
        items = list(InvoiceItem.objects.filter(invoice=invoice))
        off = sum((Decimal(str(i.discount_amount or 0)) for i in items), Decimal('0'))
        labels = []
        for item in items:
            label = (item.detail or '').strip()
            if item.discount_amount and label and label not in labels:
                labels.append(label)
        label = ' + '.join(labels)[:120] or 'Discount'
        is_bundle = bool(labels) and all(l.lower() in bundle_names for l in labels)
        paid = InvoicePayment.objects.filter(invoice=invoice, status='completed').exists()
        if paid or invoice.status in ('paid', 'cancelled'):
            invoice.discount_auto = False
            invoice.save(update_fields=['discount_auto'])
            continue
        for item in items:
            if not item.discount_amount:
                continue
            if (item.detail or '').strip() in labels and (item.detail or '').strip().lower() in bundle_names:
                item.detail = ''
            item.discount_amount = Decimal('0')
            item.discount_percent = Decimal('0')
            item.amount = Decimal(str(item.unit_price or 0)) * (item.quantity or 0)
            item.save(update_fields=['detail', 'discount_amount', 'discount_percent', 'amount'])
        invoice.discount_amount = off
        invoice.discount_label = label
        invoice.discount_auto = is_bundle
        invoice.save(update_fields=['discount_amount', 'discount_label', 'discount_auto'])


